FROM festival_info
WHERE source_type = #{sourceType}
  AND external_content_id = #{externalContentId}

mapper.insert:
INSERT INTO festival_info_translations (
    info_id, language_code, event_place, address, play_time, use_time, sponsor1, sponsor2
)
VALUES (
    #{infoId}, #{languageCode}, #{eventPlace}, #{address},
    #{playTime}, #{useTime}, #{sponsor1}, #{sponsor2}
)

mapper.update:
UPDATE festival_info_translations
SET event_place = #{eventPlace},
    address = #{address},
    play_time = #{playTime},
    use_time = #{useTime},
    sponsor1 = #{sponsor1},
    sponsor2 = #{sponsor2}
WHERE info_id = #{infoId}
  AND language_code = #{languageCode}

mapper.delete:
